#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: set up a Slack bot token for `mcp-faster slack-tickets` and add the
# server to Claude Code. The token is never printed and never written to a
# file in this repo. Claude Code keeps it in its own config (~/.claude.json).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
APP_NAME="mcp-faster tickets"

# slack_get METHOD QUERY: calls the Slack API. The token goes in through stdin, so it never shows in `ps`.
slack_get() {
  printf 'header = "Authorization: Bearer %s"\n' "$SLACK_BOT_TOKEN" |
    curl -sS --max-time 15 --config - "https://slack.com/api/$1?$2"
}
# json_get EXPR: reads JSON on stdin, prints the value of a JS expression over `r`.
json_get() {
  node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{let r={};try{r=JSON.parse(s)}catch{};console.log(String(eval(process.argv[1])))})' "$1"
}
# check_member CHANNEL_ID: true when the bot is in the channel.
check_member() {
  [[ "$(slack_get conversations.info "channel=$1" | json_get 'r.ok && r.channel.is_member')" == "true" ]]
}
valid_channel() { [[ "$1" =~ ^[CG][A-Z0-9]{8,}$ ]]; }

command -v node >/dev/null 2>&1 || { echo "Node is needed. Install Node 24 or newer first."; exit 1; }
command -v claude >/dev/null 2>&1 || { echo "The claude command is needed. Install Claude Code first."; exit 1; }

banner "Slack tickets setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create the Slack app"
say "The app is a bot that can read channels it is invited to, reply in threads and add reactions."
MANIFEST="display_information:
  name: $APP_NAME
features:
  bot_user:
    display_name: $APP_NAME
    always_online: false
oauth_config:
  scopes:
    bot:
      - channels:history
      - channels:read
      - channels:join
      - reactions:read
      - reactions:write
      - chat:write
      - users:read
settings:
  org_deploy_enabled: false
  socket_mode_enabled: false
  token_rotation_enabled: false"
if command -v pbcopy >/dev/null 2>&1; then
  printf '%s\n' "$MANIFEST" | pbcopy
  say "The app manifest is on your clipboard."
else
  say "Copy this manifest:"
  printf '\n%s\n\n' "$MANIFEST"
fi
open_url "https://api.slack.com/apps?new_app=1"
step "Choose \"From a manifest\" (the label may read \"From an app manifest\")."
step "Pick your workspace and continue."
step "Choose the YAML tab, replace what is there with the manifest, and continue."
step "Review the 7 bot scopes and click Create."
note "You need permission to add apps to the workspace. If Slack asks for admin approval, stop here and get it."
pause "Press Enter when the app exists"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Install the app and copy its token"
step "In the app's left menu, open \"Install App\"."
step "Click \"Install to Workspace\" and allow it."
step "Copy the \"Bot User OAuth Token\". It starts with xoxb-."
while true; do
  SLACK_BOT_TOKEN=""
  ask_secret SLACK_BOT_TOKEN "Paste the bot token (input is hidden):"
  if [[ "$SLACK_BOT_TOKEN" != xoxb-* ]]; then warn "That does not start with xoxb-. Copy the Bot User OAuth Token, not the signing secret."; continue; fi
  who=$(slack_get auth.test "" | json_get 'r.ok ? "ok: workspace " + r.team + ", bot " + r.user : "error: " + r.error') || who="error: could not reach Slack"
  if [[ "$who" == ok:* ]]; then printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$who"; break; fi
  warn "Slack did not accept the token ($who). Try again."
done
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Make a test channel for writes"
say "The server may post replies and reactions only in this channel. Nobody else needs to be in it."
step "In Slack, create a public channel, for example #tickets-test."
step "In that channel, type:  /invite @$APP_NAME"
step "Open the channel details (click the channel name). The Channel ID is at the bottom of the About tab."
while true; do
  ask TEST_CHANNEL_ID "Paste the test channel ID (starts with C):"
  if ! valid_channel "$TEST_CHANNEL_ID"; then warn "That is not a channel ID. It looks like C0123ABCD45."; continue; fi
  if check_member "$TEST_CHANNEL_ID"; then printf '  %s✓%s the bot is in the test channel\n' "$GREEN" "$RESET"; break; fi
  warn "The bot is not in that channel yet. Run the /invite line there, then paste the ID again."
done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Let the bot read your real ticket channel"
say "The bot can only read channels it is a member of. It will not be allowed to write in this one."
READ_CHANNEL_ID="${READ_CHANNEL_ID:-}"
if [[ -z "$READ_CHANNEL_ID" ]]; then
  step "Open the real ticket channel and copy its Channel ID the same way."
  while true; do
    ask READ_CHANNEL_ID "Paste the real ticket channel ID:"
    valid_channel "$READ_CHANNEL_ID" && break
    warn "That is not a channel ID. It looks like C0123ABCD45."
  done
fi
if [[ "$READ_CHANNEL_ID" == "$TEST_CHANNEL_ID" ]]; then
  warn "This is the same channel as the test channel, so the server may write in it."
fi
warn "Inviting the bot shows a \"joined\" line that everyone in the channel sees."
step "In the real ticket channel ($READ_CHANNEL_ID), type:  /invite @$APP_NAME"
while ! check_member "$READ_CHANNEL_ID"; do
  pause "The bot is not in $READ_CHANNEL_ID yet. Invite it, then press Enter"
done
printf '  %s✓%s the bot can read %s\n' "$GREEN" "$RESET" "$READ_CHANNEL_ID"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Add the server to Claude Code"
say "The server is added to one project folder only, so it does not start in every session."
ask PROJECT_DIR "Project folder where you work on tickets [Enter for $PWD]:"
PROJECT_DIR="${PROJECT_DIR:-$PWD}"
PROJECT_DIR="${PROJECT_DIR/#\~/$HOME}"
[[ -d "$PROJECT_DIR" ]] || { warn "No folder at $PROJECT_DIR"; exit 1; }
say "This will run, in $PROJECT_DIR:"
note "claude mcp add slack-tickets -e SLACK_BOT_TOKEN=<hidden> -e SLACK_WRITE_CHANNELS=$TEST_CHANNEL_ID -- node $REPO_DIR/src/cli.ts slack-tickets"
note "Claude Code stores the token in its own config file in your home folder, as it does for other servers."
if confirm "Add it now?"; then
  ( cd "$PROJECT_DIR"
    claude mcp remove slack-tickets >/dev/null 2>&1 || true
    claude mcp add slack-tickets \
      -e "SLACK_BOT_TOKEN=$SLACK_BOT_TOKEN" \
      -e "SLACK_WRITE_CHANNELS=$TEST_CHANNEL_ID" \
      -- node "$REPO_DIR/src/cli.ts" slack-tickets >/dev/null ) &&
    DONE_MSG="slack-tickets is added to Claude Code for $PROJECT_DIR" ||
    { SKIPPED+=("claude mcp add failed. Run it by hand from $PROJECT_DIR."); DONE_MSG=""; }
else
  SKIPPED+=("slack-tickets was not added to Claude Code")
  DONE_MSG=""
fi
unset SLACK_BOT_TOKEN

finish
[[ -n "$DONE_MSG" ]] && note "$DONE_MSG"
note "Reads: any channel the bot is in. Writes: only $TEST_CHANNEL_ID."
note "Try it: start claude in that folder and ask it to list the open tickets in $READ_CHANNEL_ID."
printf '\n'
